\begin{ex}%[6H5N1]
\immini[thm]{
Tìm trục đối xứng của hình ảnh sau
}{
\begin{tikzpicture}

    % Kích thước của lá cờ Anh
    \def\flagWidth{8}
    \def\flagHeight{5}

    % Vẽ nền cờ màu trắng
    \fill[white] (0,0) rectangle (\flagWidth,\flagHeight);

    % Vẽ đường thẳng đứng màu đỏ ở giữa
    \fill[red] ({\flagWidth/2-0.3}, 0) rectangle ({\flagWidth/2+0.3}, \flagHeight);

    % Vẽ đường ngang màu đỏ ở giữa
    \fill[red] (0, {\flagHeight/2-0.3}) rectangle (\flagWidth, {\flagHeight/2+0.3});

\end{tikzpicture}
}
